function dec(s) { return JSON.parse(decodeURIComponent(s)); }
function toySign(input, secret) {
  let h = 2166136261;
  for (const ch of (input + "|" + secret)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619) >>> 0; }
  return String(h);
}

function validateToken(token, config, nowSeconds) {
  const parts = String(token || "").split(".");
  if (parts.length !== 3) return { valid: false, reason: "malformed" };

  let header, payload;
  try {
    header = dec(parts[0]);
    payload = dec(parts[1]);
  } catch (e) {
    return { valid: false, reason: "malformed" };
  }

  if (header.alg !== config.expectedAlg) return { valid: false, reason: "alg" };
  if (toySign(parts[0] + "." + parts[1], config.secret) !== parts[2]) {
    return { valid: false, reason: "signature" };
  }
  if (typeof payload.exp !== "number" || payload.exp <= nowSeconds) {
    return { valid: false, reason: "expired" };
  }
  if (payload.aud !== config.audience) return { valid: false, reason: "audience" };

  return { valid: true, claims: payload };
}

