// resource: { type: "submission", studentId, classId }
// action:   "read" | "grade"

function can(user, action, resource) {
  // [[edit]]
  // 1. reject a falsy user or resource
  // 2. admin short-circuit
  // 3. read rules, per role
  // 4. grade rules
  // 5. default deny  <-- do not skip this line
  // [[/edit]]
