codeExercise.solution:
function can(user, action, resource) {
  if (!user || !resource) return false;
  if (user.role === "admin") return true;
  if (resource.type !== "submission") return false;

  if (action === "read") {
    if (user.role === "student") return resource.studentId === user.id;
    if (user.role === "teacher") return (user.classIds || []).indexOf(resource.classId) !== -1;
    if (user.role === "guardian") return (user.wardIds || []).indexOf(resource.studentId) !== -1;
    return false;
  }
  if (action === "grade") {
    return user.role === "teacher" && (user.classIds || []).indexOf(resource.classId) !== -1;
  }
  return false;   // default deny
}

