function corsResponse(request, config) {
  // [[edit]]
  // 1. no origin, or not an exact match in config.allowed -> return {}
  // 2. otherwise echo the matched origin, plus Vary: Origin
  // 3. add Access-Control-Allow-Credentials only when config.credentials
  // 4. on OPTIONS, add Allow-Methods and Allow-Headers from config
  return {};
