codeExercise.solution:
function corsResponse(request, config) {
  const origin = request.origin;
  if (!origin || config.allowed.indexOf(origin) === -1) return {};

  const h = { "Access-Control-Allow-Origin": origin, "Vary": "Origin" };
  if (config.credentials) h["Access-Control-Allow-Credentials"] = "true";
  if (request.method === "OPTIONS") {
    h["Access-Control-Allow-Methods"] = config.methods.join(", ");
    h["Access-Control-Allow-Headers"] = config.headers.join(", ");
  }
  return h;
}

