codeExercise.solution:
function verifyCsrf(req, session) {
  const sent = req.headers["x-csrf-token"];
  const expected = session && session.csrfToken;
  if (typeof sent !== "string" || typeof expected !== "string") return false;
  if (sent.length !== expected.length) return false;

  // constant-time compare: always examine every character
  let diff = 0;
  for (let i = 0; i < sent.length; i++) {
    diff |= sent.charCodeAt(i) ^ expected.charCodeAt(i);
  }
  return diff === 0;
}

