const SORT_COLUMNS = { date: "created_at", total: "total_cents", buyer: "buyer_name" };
const BASE = "SELECT id, buyer_name, total_cents FROM orders";

function buildOrderQuery(filters) {
  filters = filters || {};
  const where = [];
  const params = [];

  if (filters.email) { where.push("buyer_email LIKE ?"); params.push("%" + filters.email + "%"); }
  if (filters.eventId) { where.push("event_id = ?"); params.push(filters.eventId); }

  const col = SORT_COLUMNS[filters.sort] || "created_at";
  const dir = filters.dir === "desc" ? "DESC" : "ASC";

  const sql = BASE
    + (where.length ? " WHERE " + where.join(" AND ") : "")
    + " ORDER BY " + col + " " + dir;

  return { sql: sql, params: params };
}

